"""Archive public Korean Coupang API docs using insane-search, then audit coverage."""
import concurrent.futures as cf
import hashlib
import json
import re
import sys
import time
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import urljoin, urlsplit, unquote
import xml.etree.ElementTree as ET

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1] / 'docs/api'
sys.path.insert(0, str(HERE.parent / 'insane-search/skills/insane-search'))
from engine import fetch
from bs4 import BeautifulSoup
from markdownify import markdownify
from curl_cffi import requests

BASE = 'https://developers.coupang.com'
START = BASE + '/ko/api'
ROOT.mkdir(parents=True, exist_ok=True)

def dump(path, obj):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2), encoding='utf-8')

def normalized(url, base=START):
    p = urlsplit(urljoin(base, url))
    return p.scheme + '://' + p.netloc + p.path.rstrip('/')

def in_scope(url):
    p = urlsplit(url)
    return p.netloc == 'developers.coupang.com' and any(p.path == x or p.path.startswith(x + '/') for x in ['/ko/api', '/ko/getting-started', '/ko/workflows', '/ko/faq'])

def paths(url):
    rel = urlsplit(url).path.lstrip('/')
    return ROOT / 'html' / (rel + '.html'), ROOT / 'markdown' / (rel + '.md')

def links(html, url):
    soup = BeautifulSoup(html, 'html.parser')
    return {normalized(a['href'], url) for a in soup.select('a[href]') if in_scope(normalized(a['href'], url))}

def collect(url, refresh=False):
    raw, md = paths(url)
    meta = ROOT / 'metadata' / (urlsplit(url).path.lstrip('/') + '.json')
    if raw.exists() and md.exists() and meta.exists() and not refresh:
        return json.loads(meta.read_text(encoding='utf-8')), links(raw.read_text(encoding='utf-8'), url)
    result = fetch(url, enable_markdown=False, enable_extraction=False, success_selectors=['main h1'], timeout=25)
    soup = BeautifulSoup(result.content, 'html.parser')
    main = soup.select_one('main')
    if not result.ok or main is None or main.select_one('h1') is None or len(main.get_text(strip=True)) < 40:
        raise RuntimeError(f'{url}: {result.verdict} {result.summary}')
    title = main.select_one('h1').get_text(' ', strip=True)
    raw.parent.mkdir(parents=True, exist_ok=True)
    raw.write_text(result.content, encoding='utf-8')
    for a in main.select('a[href]'):
        a['href'] = urljoin(url, a['href'])
    for a in main.select('img[src]'):
        a['src'] = urljoin(url, a['src'])
    for tag in main.select('script,style'):
        tag.decompose()
    text = markdownify(str(main), heading_style='ATX', code_language='').strip()
    md.parent.mkdir(parents=True, exist_ok=True)
    md.write_text(f'<!-- Source: {url} -->\n\n{text}\n', encoding='utf-8')
    record = dict(url=url, final_url=result.final_url, title=title, fetched_utc=datetime.now(timezone.utc).isoformat(), html=str(raw.relative_to(ROOT)).replace('\\','/'), markdown=str(md.relative_to(ROOT)).replace('\\','/'), sha256=hashlib.sha256(raw.read_bytes()).hexdigest(), bytes=raw.stat().st_size, main_chars=len(main.get_text()), tables=len(main.select('table')), code_blocks=len(main.select('pre')), verdict=result.verdict, extraction_source=result.extraction_source, trace=[vars(a) for a in result.trace])
    dump(meta, record)
    return record, links(result.content, url)

def resource(url):
    r = requests.get(url, impersonate='safari', timeout=30)
    r.raise_for_status()
    return r

def main():
    seed_text = (HERE.parents[1] / '명령수행.txt').read_text(encoding='utf-8')
    reference = links(seed_text[seed_text.find('<!DOCTYPE html>'):], START)
    known = {START} | reference
    sources = {}
    for path in ['/robots.txt', '/sitemap.xml']:
        try:
            r = resource(BASE + path)
            (ROOT / path.lstrip('/')).write_bytes(r.content)
            sources[path] = dict(status=r.status_code, bytes=len(r.content))
            if path.endswith('.xml'):
                tree = ET.fromstring(r.content)
                for e in tree.iter():
                    if e.tag.endswith('loc') and e.text and in_scope(normalized(e.text)):
                        known.add(normalized(e.text))
        except Exception as e:
            sources[path] = dict(error=str(e))
    records, errors = {}, {}
    while known - records.keys() - errors.keys():
        batch = sorted(known - records.keys() - errors.keys())
        with cf.ThreadPoolExecutor(max_workers=4) as pool:
            jobs = {pool.submit(collect, url): url for url in batch}
            for job in cf.as_completed(jobs):
                url = jobs[job]
                try:
                    record, found = job.result()
                    records[url] = record
                    known.update(found)
                    print(f'OK {len(records)}/{len(known)} {url}', flush=True)
                except Exception as e:
                    errors[url] = str(e)
                    print(f'ERROR {url} {e}', flush=True)
        dump(ROOT / 'manifest.json', list(records.values()))
    # Independent second pass: re-fetch index and compare all archived links and hashes.
    fresh, found = collect(START, refresh=True)
    records[START] = fresh
    known.update(found)
    for rec in list(records.values()):
        known.update(links((ROOT / rec['html']).read_text(encoding='utf-8'), rec['url']))
    for url in sorted((known - records.keys()) | errors.keys()):
        try:
            rec, extra = collect(url, refresh=True)
            records[url] = rec
            known.update(extra)
            errors.pop(url, None)
        except Exception as e:
            errors[url] = str(e)
    invalid = [r['url'] for r in records.values() if hashlib.sha256((ROOT / r['html']).read_bytes()).hexdigest() != r['sha256'] or not (ROOT / r['markdown']).stat().st_size]
    # Preserve images and downloadable attachments referenced by the document body.
    assets = set()
    for rec in records.values():
        soup = BeautifulSoup((ROOT / rec['html']).read_text(encoding='utf-8'), 'html.parser')
        for el in soup.select('main img[src], main a[href]'):
            u = urljoin(rec['url'], el.get('src') or el.get('href'))
            if el.name == 'img' or re.search(r'\.(pdf|xlsx?|csv|zip|json|ya?ml|docx?|png|jpe?g|svg)(?:[?#]|$)', u, re.I):
                if u.startswith('https://'):
                    assets.add(u)
    asset_records = []
    for url in sorted(assets):
        name = hashlib.sha256(url.encode()).hexdigest()[:12] + '-' + re.sub(r'[^\w.\-]', '_', unquote(urlsplit(url).path.split('/')[-1]))[:100]
        target = ROOT / 'assets' / name
        try:
            target.parent.mkdir(parents=True, exist_ok=True)
            response = resource(url)
            target.write_bytes(response.content)
            asset_records.append(dict(url=url, file='assets/' + name, bytes=len(response.content), sha256=hashlib.sha256(response.content).hexdigest()))
        except Exception as e:
            asset_records.append(dict(url=url, error=str(e)))
    dump(ROOT / 'assets.json', asset_records)
    dump(ROOT / 'manifest.json', sorted(records.values(), key=lambda r:r['url']))
    audit = dict(checked_utc=datetime.now(timezone.utc).isoformat(), scope='Korean /ko/api and linked getting-started, workflows, faq; other locales and separate Travel API excluded', reference_urls=len(reference), discovered_urls=len(known), saved_pages=len(records), api_pages=sum('/ko/api' in u for u in records), missing_urls=sorted(known - records.keys()), errors=errors, invalid_files=invalid, fresh_index_urls=len(found), assets=len(assets), asset_errors=[a for a in asset_records if 'error' in a], discovery_sources=sources)
    dump(ROOT / 'audit.json', audit)
    lines = ['# 쿠팡 API 문서 다운로드', '', f'수집: {audit["checked_utc"]}', '', '- 원문 HTML: `html/`', '- 읽기용 Markdown: `markdown/`', '- 문서별 출처·해시·수집 기록: `manifest.json`, `metadata/`', '- 누락 검토 결과: `audit.json`', '- 이미지·첨부파일: `assets/`, `assets.json`', '', f'문서 {len(records)}개 / 발견 {len(known)}개, 누락 {len(audit["missing_urls"])}개, 파일 검증 오류 {len(invalid)}개.', '', '범위: 한국어 API 문서 및 연결된 시작하기·워크플로·FAQ. 다른 언어와 별도 Travel API 사이트는 제외.', '', '## 문서 목록', '']
    lines += [f'- [{r["title"]}]({r["markdown"]}) — [원문]({r["url"]})' for r in sorted(records.values(), key=lambda r:r['url'])]
    (ROOT / 'README.md').write_text('\n'.join(lines) + '\n', encoding='utf-8')
    print(json.dumps(audit, ensure_ascii=True, indent=2))

if __name__ == '__main__':
    main()

